declare(strict_types=1);require '../config/db.php';require '../config/auth.php';require_role('admin','login.php');$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT receipt_path FROM appointments WHERE id=?");$s->execute([$id]);$a=$s->fetch();if(!$a||!$a['receipt_path']){http_response_code(404);exit('Receipt not found.');}$base=realpath(__DIR__.'/../uploads/payment_receipts');$file=realpath(__DIR__.'/../'.$a['receipt_path']);if(!$base||!$file||!str_starts_with($file,$base.DIRECTORY_SEPARATOR)||!is_file($file)){http_response_code(404);exit('Receipt not found.');}$f=new finfo(FILEINFO_MIME_TYPE);$mime=$f->file($file);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true)){http_response_code(415);exit('Unsupported receipt.');}header('Content-Type: '.$mime);header('Content-Length: '.filesize($file));header('Cache-Control: private, no-store');readfile($file);
